interface Version { readonly effective: number; readonly terms: Terms }   // epoch ms, UTC
interface Contract { readonly id: string; readonly history: readonly Version[] }

const asOf = (c: Contract, on: Date): Version | undefined =>
  c.history.findLast(v => v.effective <= on.getTime());   // undefined = Missing Version

const amend = (c: Contract, effective: Date, terms: Terms): Contract => ({  // new value
  ...c,
  history: [...c.history, { effective: effective.getTime(), terms }]
    .sort((a, b) => a.effective - b.effective),
});
